messages.body_plain:
Hi,

 here is a source code that allows estimate interactions for Conjoint Analysis in R. Obtained matrix xInteractions can be applied as input in partutilities (part-worth utility estimation) or others that can be obtained from: http://keii.ae.jgora.pl/nauka/procedury.zip.

subsets <- function(n, r) {
  if(is.numeric(n) & length(n) == 1) v <- 1:n else {
    v <- n
    n <- length(v)
  }
    subs <- function(n, r, v)
      if(r <= 0) NULL else
      if(r >= n) matrix(v[1:n], nrow = 1) else
      rbind(cbind(v[1], subs(n - 1, r - 1, v[-1])),
      subs(n - 1, r , v[-1]))
      subs(n, r, v)
} 

