interval<-function(x,begins){
 output<-length(begins)
 for(i in 1:(length(begins)-1)){
  if((begins[i]<=x) &&  (x<begins[i+1])){
   output<-i
  }
 }
 output
}

allowed <-function(indexes,begins){
 resul<-TRUE
 for(i in 1:(length(indexes)-1))
 for(j in (i+1):length(indexes)){
  if(interval(indexes[i],begins)==interval(indexes[j],begins))resul<-FALSE  
 }
 resul
}

x<-as.matrix(x)
numVariables<-ncol(x)
interLevels<-2

maxComb<-interLevels+1

levels<-c(2,1,1)


begins<-seq(along.with=levels)
begins[1]<-1
for(i in 2:length(levels)){
  begins[i]<-begins[i-1]+levels[i-1]
}

xInterakcje<-x

for(i in 1:interLevels){
  for(j in  1:nrow(subsets(numVariables,i+1))){
    indexes<-subsets(numVariables,i+1)[j,]
    print(paste(paste(indexes,collapse=","),allowed(indexes,begins)))
    if(allowed(indexes,begins)){
     output<-x[,indexes[1]]
     for(k in 2:(i+1)){
       output<-output*x[,indexes[k]]
     }
     xInterakcje<-cbind(xInterakcje,output)
 }
  }
}
nam<-paste("x",1:numVariables,sep="")
for(i in 1:interLevels){
  for(j in  1:nrow(subsets(numVariables,i+1))){
    indexes<-subsets(numVariables,i+1)[j,]
    if(allowed(indexes,begins)){
     nam<-c(nam,paste(paste("x",indexes,sep=""),collapse="_"))
 }
  }
}
colnames(xInterakcje)<-nam

print(xInterakcje)

x<-as.data.frame(xInterakcje)

